def fib_memo(n: int):
    """Return n-th Fibonacci number using memoization.
    >>> fib_memo(10)
    55
    >>> fib_memo(1)
    1
    >>> fib_memo(8)
    21
    """
    memo = {}
    def helper(n):
        if n in memo:
            return memo[n]
        elif n == 0:
            return 0
        elif n == 1:
            return 1
        else:
            memo[n] = helper(n - 1) + helper(n - 2)
            return memo[n]
    return helper(n)


