    for i in range(2, int(n**0.5) + 1):
        if n % i == 0 and is_prime(i):
            largest_factor = i
            # Check if the corresponding factor (n // i) is a prime and update largest_factor if it is
            if is_prime(n // i):
                largest_factor = n // i
    # If n itself is a prime number, it will not be updated in the loop, so return n
    if largest_factor == 1 and is_prime(n):
        return n
    return largest_factor

