def string_to_sha1(text):
    """
    Given a string 'text', return its sha1 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_sha1('Hello world') == '2ef7bde608ce5404e97d5f042f95f89f1c232871'
    """
    import hashlib
    if not text:
        return None
    return hashlib.sha1(text.encode()).hexdigest()


def string_to_sha256(text):
    """
    Given a string 'text', return its sha256 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_sha256('Hello world') == 'a591a6d40bf420404a011733cfb7b190d62c65bf0bcda32b57b277d9ad9f146e'
    """
    import hashlib
    if not text:
        return None
    return hashlib.sha256(text.encode()).hexdigest()


def test_string_to_md5():
    assert string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    assert string_to_md5('') is None


def test_string_to_sha1():
    assert string_to_sha1('Hello world') == '2ef7bde608ce5404e97d5f042f95f89f1c232871'
    assert string_to_sha1('') is None


def test_string_to_sha256():
    assert string_to_sha256('Hello world') == 'a591a6d40bf420404a011733cfb7b190d62c65bf0bcda32b57b277d9ad9f146e'
    assert string_to_sha256('') is None
